import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String chars = next();
        long n = Long.parseLong(next());
        String[] w = new String[(int) n];
        for (int i = 0; i < w.length; i++) w[i] = next();

        Map<Character, Integer> have = new HashMap<>();
        for (int i = 0; i < chars.length(); i++) have.merge(chars.charAt(i), 1, Integer::sum);
        long total = 0;
        for (int i = 0; i < n; i++) {
            Map<Character, Integer> need = new HashMap<>();
            for (int j = 0; j < w[i].length(); j++) need.merge(w[i].charAt(j), 1, Integer::sum);
            boolean ok = true;
            for (Map.Entry<Character, Integer> entry : need.entrySet()) {
                if (have.getOrDefault(entry.getKey(), 0) < entry.getValue()) ok = false;
            }
            if (ok) total += w[i].length();
        }
        System.out.println(total);
    }
}
